  './store.js': { saveReport: async (...args) => {
    events.push(['save', ...args]);
    if (failure === 'save') throw new Error('save failed');
  } },
  './mail.js': { sendMail: async (...args) => {
    events.push(['send', ...args]);
    if (failure === 'send') throw new Error('send failed');
  } },
  './report_render.js': Object.fromEntries(Object.entries(renderers).map(([name, render]) => [name, (...args) => {
    events.push(['render', name, ...args]);
    return render(...args);
  }]))
};
const module = new SourceTextModule(await readFile('src/report_mailer.js', 'utf8'));
await module.link((specifier) => {
  const exports = mocks[specifier];
  return new SyntheticModule(Object.keys(exports), function () {
    for (const [name, value] of Object.entries(exports)) this.setExport(name, value);
  });
});
await module.evaluate();
