  assert.deepEqual(await module.namespace[name](...args), { shopId: shop.id, kind, bytes: html.length });
  assert.deepEqual(events, [
    ['render', renderer, ...args],
    ['save', "'`${kind}-${shop.id}-${date}`, html],
    ['"'send', shop.email, subject, html]
  ]);
  for (failure of ['save', 'send']) {
    events.length = 0;
    await assert.rejects(module.namespace[name](...args), new RegExp("'`${failure} failed`));
    assert.deepEqual(events.map(([step]) => step), failure === '"'save' ? ['render', 'save'] : ['render', 'save', 'send']);
  }
}
